// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { delayRender, continueRender } from '../remotionShim';

// Library: none — native interpolate/spring

if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf") ? "opentype" : url.endsWith(".woff2") ? "woff2" : url.endsWith(".woff") ? "woff" : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font.load()
      .then(() => { document.fonts.add(font); continueRender(handle); })
      .catch((err) => { console.log(`Error loading ${family}`, err); continueRender(handle); });
  };
  loadCustomFont("Believe-Font", "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/6e3f2edcbb584480b2d9a1404eee140c.otf");
}



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#030303",
  transparentBackground = false,
  durationInSeconds = 12,
  primaryColor = "#FEBF10",
  startLabel = "YEAR 1",
  startLabelFontFamily = "Believe-Font",
  endLabel = "YEAR 15",
  endLabelFontFamily = "Believe-Font",
  ghostWords = [
    { text: "STOP.", fontFamily: "Believe-Font", timelinePosition: 0.2, yOffset: -80 },
    { text: "GIVE UP.", fontFamily: "Believe-Font", timelinePosition: 0.4, yOffset: 120 },
    { text: "IT'S ENOUGH.", fontFamily: "Believe-Font", timelinePosition: 0.6, yOffset: -100 },
    { text: "MOVE ON.", fontFamily: "Believe-Font", timelinePosition: 0.8, yOffset: 90 }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline geometry
  const startX = width * 0.25;
  const endX = width * 0.75;
  const centerY = height * 0.5;
  const trackLength = endX - startX;

  // Core timings
  const totalFrames = durationInSeconds * fps;
  const introDuration = 30;
  const endHoldDuration = 90; // Frames at the end for pulse and camera push
  const travelStartFrame = introDuration;
  const travelEndFrame = totalFrames - endHoldDuration;
  
  // Progress calculations
  const dotProgress = interpolate(frame, [travelStartFrame, travelEndFrame], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const currentX = interpolate(dotProgress, [0, 1], [startX, endX]);
  
  // Master scene transformations
  const masterOpacity = interpolate(frame, [0, introDuration], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) * 
                        interpolate(frame, [totalFrames - 30, totalFrames], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const cameraScale = interpolate(frame, [travelEndFrame, totalFrames], [1, 1.05], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill 
        style={{ 
          opacity: masterOpacity, 
          transform: `scale(${cameraScale})`,
          transformOrigin: `${endX}px ${centerY}px`,
          transition: "none"
        }}
      >
        {/* Subtle Ambient Background Glow */}
        <div style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: width * 0.8,
          height: height * 0.6,
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(ellipse at center, ${primaryColor}15 0%, transparent 60%)`,
          filter: `blur(${100 * s}px)`,
          opacity: 0.5,
          pointerEvents: "none"
        }} />

        {/* Ghost Words */}
        {ghostWords.map((word, i) => {
          // Fade in before dot reaches position, fade out just before dot arrives
          const wordX = startX + trackLength * word.timelinePosition;
          
          const fadeInStart = Math.max(0, word.timelinePosition - 0.15);
          const fadeInEnd = Math.max(0, word.timelinePosition - 0.10);
          const fadeOutStart = Math.max(0, word.timelinePosition - 0.05);
          const fadeOutEnd = word.timelinePosition;

          const wordOpacity = interpolate(
            dotProgress,
            [fadeInStart, fadeInEnd, fadeOutStart, fadeOutEnd],
            [0, 0.12, 0.12, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Hide completely if opacity is 0 to avoid rendering invisible elements unnecessarily
          if (wordOpacity === 0 && (dotProgress < fadeInStart || dotProgress > fadeOutEnd)) return null;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: wordX,
                top: centerY + (word.yOffset * s),
                transform: "translate(-50%, -50%)",
                color: "#FFFFFF",
                fontFamily: word.fontFamily,
                fontSize: 32 * s,
                letterSpacing: 8 * s,
                opacity: wordOpacity,
                filter: `blur(${3 * s}px)`,
                whiteSpace: "nowrap",
                transition: "none"
              }}
            >
              {word.text}
            </div>
          );
        })}

        {/* Timeline Base Track */}
        <div style={{
          position: "absolute",
          left: startX,
          top: centerY - (1 * s),
          width: trackLength,
          height: 2 * s,
          backgroundColor: "#ffffff",
          opacity: 0.15,
          borderRadius: 2 * s,
          transition: "none"
        }} />

        {/* Timeline Active Track */}
        <div style={{
          position: "absolute",
          left: startX,
          top: centerY - (1 * s),
          width: currentX - startX,
          height: 2 * s,
          backgroundColor: primaryColor,
          boxShadow: `0 0 ${12 * s}px ${primaryColor}80`,
          borderRadius: 2 * s,
          transition: "none"
        }} />

        {/* Start Label & Dot */}
        <div style={{
          position: "absolute",
          left: startX - (30 * s),
          top: centerY,
          transform: "translate(-100%, -50%)",
          color: "#FFFFFF",
          fontFamily: startLabelFontFamily,
          fontSize: 24 * s,
          letterSpacing: 2 * s,
          opacity: 0.7,
          transition: "none"
        }}>
          {startLabel}
        </div>
        <div style={{
          position: "absolute",
          left: startX,
          top: centerY,
          width: 8 * s,
          height: 8 * s,
          transform: "translate(-50%, -50%)",
          backgroundColor: primaryColor,
          borderRadius: "50%",
          opacity: 0.5,
          transition: "none"
        }} />

        {/* End Label & Dot Base */}
        <div style={{
          position: "absolute",
          left: endX + (30 * s),
          top: centerY,
          transform: "translate(0, -50%)",
          color: "#FFFFFF",
          fontFamily: endLabelFontFamily,
          fontSize: 24 * s,
          letterSpacing: 2 * s,
          opacity: 0.7,
          transition: "none"
        }}>
          {endLabel}
        </div>
        <div style={{
          position: "absolute",
          left: endX,
          top: centerY,
          width: 8 * s,
          height: 8 * s,
          transform: "translate(-50%, -50%)",
          backgroundColor: "#ffffff",
          borderRadius: "50%",
          opacity: 0.2,
          transition: "none"
        }} />

        {/* End Pulse Animation (Triggers when dot arrives) */}
        {[0, 1, 2].map((i) => {
          const pulseDelay = travelEndFrame + (i * 10);
          // Opacity is 0 before delay, spikes, then fades
          const pOpacity = interpolate(frame, [pulseDelay, pulseDelay + 10, pulseDelay + 60], [0, 0.4, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const pScale = interpolate(frame, [pulseDelay, pulseDelay + 60], [0.5, 3], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          
          if (frame < pulseDelay) return null;

          return (
            <div
              key={`pulse-${i}`}
              style={{
                position: "absolute",
                left: endX,
                top: centerY,
                width: 60 * s,
                height: 60 * s,
                transform: `translate(-50%, -50%) scale(${pScale})`,
                border: `${2 * s}px solid ${primaryColor}`,
                borderRadius: "50%",
                opacity: pOpacity,
                boxShadow: `0 0 ${20 * s}px ${primaryColor} inset`,
                transition: "none"
              }}
            />
          );
        })}

        {/* The Traveling Glowing Dot */}
        <div style={{
          position: "absolute",
          left: currentX,
          top: centerY,
          width: 14 * s,
          height: 14 * s,
          transform: "translate(-50%, -50%)",
          backgroundColor: "#ffffff", // Crisp white center like the reference
          borderRadius: "50%",
          boxShadow: `
            0 0 ${10 * s}px ${primaryColor},
            0 0 ${30 * s}px ${primaryColor},
            0 0 ${60 * s}px ${primaryColor}80
          `,
          transition: "none",
          zIndex: 10
        }} />

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ComponentName;